SELECT CASE WHEN s.rating >= 3.9 THEN 'high' WHEN s.rating >= 2.2 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(DISTINCT p.stock_qty) AS unique_categorys FROM products p INNER JOIN suppliers s ON p.supplier_id = s.id GROUP BY CASE WHEN s.rating >= 3.9 THEN 'high' WHEN s.rating >= 2.2 THEN 'mid' ELSE 'low' END ORDER BY unique_categorys;
